extends Node2D
## A6 Effect A trigger: one hit burst per played "damaged" event (CHANGE-BRIEF §1, rules A1-A6).
## Presentation only: it READS main's state (played_events, pieces, paused, time_scale) and
## never writes it. Every look value lives in res://effects/hit_burst.tscn; this script only
## instances the scene, places it, sets `emitting` and `speed_scale`, and frees it.
##
## A child of Main with process_priority 10, so it runs after main's _process (priority 0) in
## the same frame and sees an impact on the frame _cue_impact plays it (A1).
## The node sits at the origin with z 0, so each burst's own z_index 2 stays absolute.
##
## A3 retrigger = overlap: every event gets a NEW instance; earlier bursts keep playing.
## A4: bursts are children of this node, never of an archer. A reset (R, play again, start)
##     clears main.played_events; this node sees the list shrink and frees every live burst.
## A5: speed_scale follows main.time_scale, and is 0 while main.paused.
## A6: a burst frees itself when its longest emitter (Dust) emits `finished`.

const MainScript = preload("res://game/main.gd")
const HitBurstScene: PackedScene = preload("res://effects/hit_burst.tscn")

const HIT_OFFSET: Vector2 = Vector2(0.0, -40.0) ## base-disc centre -> body (CHANGE-BRIEF §1 "Where")
const LONGEST_EMITTER: String = "Dust"

## Bursts created since start (read by tests; never reset).
var spawned: int = 0

var _main: MainScript
var _read: int = 0 ## how many of main.played_events this node has looked at


func _ready() -> void:
	_main = get_parent() as MainScript


func _process(_delta: float) -> void:
	if _main == null:
		return
	var events: Array[Dictionary] = _main.played_events
	if events.size() < _read:
		clear_bursts()
		_read = 0
	while _read < events.size():
		var ev: Dictionary = events[_read]
		_read += 1
		if String(ev["type"]) == "damaged":
			_spawn(ev)
	var speed: float = _speed()
	for burst: Node in get_children():
		for emitter: Node in burst.get_children():
			(emitter as CPUParticles2D).speed_scale = speed


## Live bursts, oldest first (excludes ones already queued for deletion).
func live_bursts() -> Array[Node2D]:
	var out: Array[Node2D] = []
	for burst: Node in get_children():
		if not burst.is_queued_for_deletion():
			out.append(burst as Node2D)
	return out


func clear_bursts() -> void:
	for burst: Node in get_children():
		remove_child(burst)
		burst.queue_free()


func _speed() -> float:
	return 0.0 if _main.paused else _main.time_scale


func _spawn(ev: Dictionary) -> void:
	var piece: Node2D = _main.pieces.get(ev["unit"])
	if piece == null:
		return
	var burst: Node2D = HitBurstScene.instantiate() as Node2D
	add_child(burst)
	burst.position = piece.position + HIT_OFFSET
	var longest: CPUParticles2D = burst.get_node(LONGEST_EMITTER) as CPUParticles2D
	longest.finished.connect(burst.queue_free)
	var speed: float = _speed()
	for emitter: Node in burst.get_children():
		var e: CPUParticles2D = emitter as CPUParticles2D
		e.speed_scale = speed
		e.emitting = true
	spawned += 1

	var groups: Array[Dictionary] = []
	for ev: Dictionary in events:
		if ev["type"] == "attack" or ev["type"] == "attack_cancelled":
			groups.append({"head": ev, "hits": []})
		elif not groups.is_empty():
			(groups[-1]["hits"] as Array).append(ev)
	var t: float = 0.0
	for g: Dictionary in groups:
		var head: Dictionary = g["head"]
		if head["type"] == "attack":
			_schedule(t, _cue_draw.bind(head))
			_schedule(t + DRAW_LEAD, _cue_arrow.bind(head))
			_schedule(t + DRAW_LEAD + ARROW_TIME, _cue_impact.bind(head, g["hits"]))
			_schedule(t + DRAW_LEAD + ARROW_TIME + ATTACK_RECOVER, _cue_attacker_idle.bind(head))
			t += DRAW_LEAD + ARROW_TIME + ATTACK_RECOVER + ATTACK_GAP
		else:
			_schedule(t, _cue_cancel.bind(head))
			t += CANCEL_TIME
	_schedule(t + ATTACK_TAIL, _after_attacks)


func _cue_draw(head: Dictionary) -> void:
	var p: PieceScript = pieces[head["unit"]]
	var target: Vector2i = head["target"]
	if target.x != p.cell.x:
		p.set_facing(1 if target.x > p.cell.x else -1)
	p.set_state("draw")
	played_events.append(head)


func _cue_arrow(head: Dictionary) -> void:
	var p: PieceScript = pieces[head["unit"]]
	var target: Vector2i = head["target"]
	var from: Vector2 = p.position + Vector2(14.0 * p.facing, -36.0)
	var to: Vector2 = _cell_rect(target).get_center() + Vector2(0.0, 2.0)
	_arrows.append({"from": from, "to": to, "t": 0.0})


func _cue_impact(head: Dictionary, hits: Array) -> void:
	if head["team"] == RulesScript.PLAYER:
		has_marked_target = false # the marked square stays visible until this hit
	for ev: Dictionary in hits:
		played_events.append(ev)
		var p: PieceScript = pieces[ev["unit"]]
		match String(ev["type"]):
			"damaged":
				display_hp[ev["unit"]] = int(ev["hp_after"])
				audio.on_event(ev) # SFX-HIT / SFX-HURT at the same moment as the pips change
				_floaters.append({"pos": p.position + Vector2(0.0, -92.0), "text": "-%d" % int(ev["amount"]),
					"color": COL_TARGET, "t": 0.0})
				if int(ev["hp_after"]) > 0:
					p.show_hurt()
			"killed":
				p.set_state("defeat")


func _cue_attacker_idle(head: Dictionary) -> void:
	var p: PieceScript = pieces[head["unit"]]
	if p.state == "draw":
		p.set_state("idle")


func _cue_cancel(head: Dictionary) -> void:
	played_events.append(head)
	if head["team"] == RulesScript.PLAYER:
		has_marked_target = false
	var p: PieceScript = pieces[head["unit"]]
	_floaters.append({"pos": p.position + Vector2(0.0, -92.0), "text": "no target", "color": COL_HUD_TEXT, "t": 0.0})


func _after_attacks() -> void:
	has_marked_target = false
	last_result = rules.end_turn()
	match String(last_result["result"]):
		"won":

	for i: int in RulesScript.ARCHER_HP:
		var pos: Vector2 = p.position + Vector2(-13.5 + i * 9.0, 13.0)
		ci.draw_circle(pos, 3.5, team_col if i < hp else Color(COL_INK, 0.25))
# attack order numbers during attack planning
if state == State.PLAN_ATTACK:
	var order: Array[String] = rules.attack_order()
	for i: int in order.size():
		var p: PieceScript = pieces[order[i]]
		var pos: Vector2 = p.position + Vector2(0.0, -108.0)
		ci.draw_circle(pos, 11.0, COL_INK)
		ci.draw_string(font, pos + Vector2(-11.0, 6.0), "%d" % (i + 1), HORIZONTAL_ALIGNMENT_CENTER, 22.0, 16, COL_HUD_TEXT)
# arrows in flight
for a: Dictionary in _arrows:
	var s: float = clampf(float(a["t"]) / ARROW_TIME, 0.0, 1.0)
	var from: Vector2 = a["from"]
	var to: Vector2 = a["to"]
	var pos: Vector2 = from.lerp(to, s) + Vector2(0.0, -ARROW_ARC * 4.0 * s * (1.0 - s))
	var vel: Vector2 = (to - from) + Vector2(0.0, -ARROW_ARC * 4.0 * (1.0 - 2.0 * s))
	var dir: Vector2 = vel.normalized()
	var side: Vector2 = Vector2(-dir.y, dir.x)
	ci.draw_line(pos - dir * 30.0, pos, Color("#5A3A22"), 3.0)
	ci.draw_colored_polygon(PackedVector2Array([pos + dir * 8.0, pos + side * 4.5, pos - side * 4.5]), COL_INK)
	ci.draw_line(pos - dir * 30.0, pos - dir * 36.0 + side * 5.0, COL_CARD, 2.0)
	ci.draw_line(pos - dir * 30.0, pos - dir * 36.0 - side * 5.0, COL_CARD, 2.0)
# floating numbers
for f: Dictionary in _floaters:
	var k: float = float(f["t"]) / FLOAT_TIME
	var pos: Vector2 = (f["pos"] as Vector2) + Vector2(-60.0, -30.0 * k)
	var col: Color = f["color"]
	ci.draw_string_outline(font, pos, String(f["text"]), HORIZONTAL_ALIGNMENT_CENTER, 120.0, 28, 6, Color(COL_INK, 1.0 - k))

const COL_CARD: Color = Color("#F3E9D2")
const COL_HUD_TEXT: Color = Color("#F3E9D2")

const ACTION_ORDER: Array[String] = ["lt_confirm", "lt_left", "lt_right", "lt_up", "lt_down", "lt_stay",
	"lt_retry", "lt_pause", "lt_music", "lt_sfx", "lt_debug"]
const ACTION_KEYS: Dictionary = {
	"lt_confirm": [KEY_ENTER, KEY_KP_ENTER],
	"lt_left": [KEY_LEFT, KEY_A],
	"lt_right": [KEY_RIGHT, KEY_D],
	"lt_up": [KEY_UP, KEY_W],
	"lt_down": [KEY_DOWN, KEY_S],
	"lt_stay": [KEY_SPACE],
	"lt_retry": [KEY_R],
	"lt_pause": [KEY_P, KEY_ESCAPE],

## Combat. player_targets: unit id -> Vector2i target square (must be in valid_targets()).
## Events: attack {unit, target}; damaged {unit, by, amount, hp_after} for EVERY unit in the square
## (friendly fire included); killed; attack_cancelled when the square has no enemy left.
## All events of one shot share the same "attack" key.
func resolve_attacks(player_targets: Dictionary) -> Array[Dictionary]:
	var events: Array[Dictionary] = []
	if phase != "attack":
		push_error("Rules.resolve_attacks called in phase '%s'" % phase)
		return events
	var targets: Dictionary = enemy_targets()
	for id: Variant in player_targets:
		var u: Dictionary = get_unit(String(id))
		if u.is_empty() or u["team"] != PLAYER or int(u["hp"]) <= 0:
			continue
		if typeof(player_targets[id]) != TYPE_VECTOR2I:
			continue # null = hold fire
		var t: Vector2i = player_targets[id]
		if valid_targets(u["id"]).has(t):
			targets[u["id"]] = t
	for id: String in attack_order(targets):
		var u: Dictionary = get_unit(id)
		if int(u["hp"]) <= 0:
			continue # killed before its turn: no attack
		if not targets.has(id):
			continue
		var target: Vector2i = targets[id]
		_attack_serial += 1
		var key: String = "%d:%d" % [turn, _attack_serial]
		if target.x != int(u["col"]):
			u["facing"] = 1 if target.x > int(u["col"]) else -1
		var foe: String = other_team(u["team"])
		var has_foe: bool = false
		for v: Dictionary in units_at(target):
			if v["team"] == foe:
				has_foe = true
		if not has_foe:
			events.append({"type": "attack_cancelled", "unit": id, "team": u["team"], "target": target, "attack": key})
			continue
		events.append({"type": "attack", "unit": id, "team": u["team"], "target": target, "attack": key})
		var dmg: int = int(config["player_damage"] if u["team"] == PLAYER else config["enemy_damage"])
		for v: Dictionary in units_at(target):
			v["hp"] = maxi(0, int(v["hp"]) - dmg)
			events.append({"type": "damaged", "unit": v["id"], "team": v["team"], "by": id, "by_team": u["team"],
				"amount": dmg, "hp_after": v["hp"], "attack": key})
